const LOG=[
 {v:'3.5',d:'2026-11-19',ar:['⚖️ توازن جديد للعبة: الجنود يزيدون بشكل واقعي (حوالي 30 ألف بعد دقيقتين بدل ما توصل مليون)، والقيم يطول 15 لين 25 دقيقة','💰 المباني صارت أغلى: كل مبنى جديد من نفس النوع أغلى من اللي قبله بحوالي 40٪، والعصور أغلى','🏙️ المدن المحايدة في الخرائط صارت أقل، وأيقونات المدن والمباني صارت أكبر','🛡️ دائرة الحصن والقبة والدفاع البحري صارت ما تتعدى حدودك، ولها خط واضح على طرفها','🤝 علامة التحالف تطلع جنب اسم أي دولة متحالف معها'],en:['⚖️ New balance: troops grow realistically (about 30K after two minutes instead of reaching a million), and a match lasts 15 to 25 minutes','💰 Buildings cost more: each new one of a kind costs about 40% more than the last, and ages cost more','🏙️ Fewer neutral cities on the maps, and bigger city and building icons','🛡️ Fort, dome and coastal gun areas stop at your border, with a clear outline on their edge','🤝 A handshake shows next to the name of every realm you are allied with']},
 {v:'3.4',d:'2026-11-19',ar:['🔢 رقم الجنود صار يمشي ورا خط الهجوم ويتحرك مع الجبهة كاملة، يميل مع الحدود ويكبر لما الجبهة تكبر','🌾 رقم الجنود ما يطلع لما تهجم على أرض فاضية، بس لما تهجم على دولة'],en:['🔢 The troop count now rides behind the attack line and moves with the whole front, tilting along the border and growing with it','🌾 No troop count when you attack empty land, only against realms']},
 {v:'3.3',d:'2026-11-19',ar:['🟢 أي أرض فاضية تحاصرها بأرضك من كل الجهات تنضم لك تلقائياً مهما كان حجمها، وتتعبّى من الأطراف للنص بأنميشن','🎯 القائمة الدائرية صارت أوضح وأجمل: تحت كل زر كلمة تشرحه (هجوم، بحري، البطاقة، صواريخ، كل الحدود)','🖱️ كلك يمين في الكمبيوتر ما يطلّع قائمة المتصفح فوق الدائرة','🗡️ السيفين لما تقضي على دولة صاروا أصغر'],en:['🟢 Any empty land you ring on every side joins you automatically whatever its size, filling from the edges inward','🎯 A clearer, nicer radial menu: a word under each button (Attack, By sea, Card, Missiles, All borders)','🖱️ Right click on PC no longer opens the browser menu over the circle','🗡️ Smaller crossed swords when you wipe out a realm']},
 {v:'3.2',d:'2026-11-19',ar:['😡 البوتات الكبار صارت ترد عليك بإيموجي: لو هجمت عليها أو غدرت فيها أو أنهيت تحالف كانت تبيه، ولو رفضت لأنها ما تثق فيك، ولو أهديتها ذهب','💬 أسباب رفض السلام والتحالف صارت كثيرة وواقعية وتتغير كل مرة','🏗️ كل المباني تنبني خلال 6 ثواني بدل 10','🔢 رقم جنود العدو على حدودك صار ثابت مثل رقمك','🎮 قائمة الجرافيكس توضح وش ضحّينا فيه بالمنخفض عشان السلاسة، ووش أضفنا بالعالي، والفصول باقية في كل المستويات'],en:['😡 Big bots now answer you with emojis: when you attack or betray them, end an alliance they wanted, refuse you for lack of trust, or receive your gold','💬 Many varied, realistic reasons when peace or alliance is refused','🏗️ Every building finishes in 6 seconds instead of 10','🔢 The enemy troop count on your border is now as steady as yours','🎮 The graphics menu explains what Low gives up for smoothness and what High adds']},
 {v:'3.1',d:'2026-11-19',ar:['🎯 قائمة دائرية: في الجوال اضغط على أي أرض، وفي الكمبيوتر كلك يمين. السيف في النص هجوم بري، والسفينة الزرقا هجوم بحري على نفس المكان، و«i» بطاقة الدولة، والمصافحة تحالف أو سلام','🚀 السيف الأحمر في الدائرة يفتح الصواريخ والهجوم من كل الحدود','⚔️ الهجوم ما يوقف لما تاخذ مدينة: تكمل الموجة بدون توقف','🔢 رقم جنودك على الجبهة صار ثابت على الحدود وما يرقص','🗡️ سيفين يتقاطعون لما تقضي على دولة','🛡️ دائرة للمنطقة اللي يحميها الدفاع البحري، وشرح أوضح للتطوير التلقائي'],en:['🎯 Radial menu: tap any land on a phone or right click on PC. The centre sword attacks by land, the blue ship attacks that spot by sea, i opens the realm card, and the handshake asks for alliance or peace','🚀 The red sword opens missiles and attack from all borders','⚔️ Attacks no longer pause when a city falls: the wave keeps rolling','🔢 Your troop count on a front now sits steady on the border','🗡️ Two crossed swords when you wipe out a realm','🛡️ A circle for the area each coastal gun protects, and clearer auto-upgrade settings']},
 {v:'3.0',d:'2026-11-19',ar:['🏰 اضغط على أرضك (بعيد عن المباني) وتطلع بطاقة دولتك: إيموجي، توقيف التجارة مع الكل، والتطوير التلقائي','⬆ التطوير التلقائي: تحدد حد ذهب ما ينزل تحته، وأقصى سعر للتطوير، وكم مبنى كل دقيقتين، ويسألك قبل كل تطوير برسالة صغيرة','😀 إيموجي فوق دولتك يشوفه الكل، وتقدر ترسل إيموجي لأي دولة من بطاقتها','⚔️ تشوف عدد جنودك على خط الهجوم، ودائرة على المكان اللي بتنزل فيه سفنك، وتاخذ جيش الدولة اللي تقضي عليها مع أنميشن السيف','🛡️ دائرة شفافة تبين المنطقة اللي يحميها الحصن وقبة الدفاع','🗺️ خريطتين جديدة: «سهول بلا بحر» و«جبال وأنهار»، وتقدر تختار عدد القبائل من 30 لين 120','🎮 الجرافيكس: منخفض ومتوسط وعالي من الإعدادات، والغرفة الأونلاين تختار لها من 2 لين 32 لاعب'],en:['🏰 Tap your land (away from buildings) for your realm card: emoji, stop trading with everyone, and auto upgrade','⬆ Auto upgrade: set gold it never goes below, the most one upgrade may cost, and how many per two minutes; it asks first with a small message','😀 Emojis over your realm for everyone to see, and you can send one to any realm from its card','⚔️ See your troops on the attack front, a circle where your ships will land, and take in the army of a realm you wipe out, with a sword animation','🛡️ A see-through circle shows the area each fort and shield dome protects','🗺️ Two new worlds: Flatlands and Highlands & rivers, and choose 30 to 120 small tribes','🎮 Graphics Low, Medium or High in Settings, and online rooms for 2 to 32 players']},
 {v:'2.9',d:'2026-11-18',ar:['👤 نظام الحسابات وصل! حساب واحد يشتغل على كل أجهزتك: الجوال والكمبيوتر بنفس الانتصارات والرتبة','📝 كيف؟ ادخل صفحة «الحساب»، اكتب اسم مستخدم (إنجليزي أو أرقام) وكلمة مرور، واضغط «سوّ حساب». انتصاراتك الحالية تنحفظ فيه','📱💻 بعدها من أي جهاز ثاني ادخل نفس الصفحة واضغط «سجّل دخول» بنفس الاسم وكلمة المرور، وتكمّل من حيث وقفت','🔒 تقدمك صار محفوظ أونلاين، ما يضيع لو مسحت المتصفح أو غيّرت جوالك. احفظ كلمة المرور زين لأنها ما تنسترجع','🖐️ صلّحنا مشكلة اللمس اللي كانت تخلي إصبع واحد يسوي زوم وما تقدر تحط مبنى','🗂️ القائمة الرئيسية صارت أرتب'],en:['👤 Accounts are here! One account works on all your devices: phone and PC with the same wins and rank','📝 How? Open the Account page, pick a username (letters or numbers) and a password, and tap Create account. Your current wins are saved into it','📱💻 Then on any other device open the same page and tap Sign in with the same username and password to carry on where you left off','🔒 Your progress is now saved online, so it is not lost if you clear the browser or change phones. Keep your password safe, it cannot be recovered','🖐️ Fixed the touch bug where one finger zoomed and you could not place buildings','🗂️ A tidier main menu']},
 {v:'2.8',d:'2026-11-18',ar:['🏆 لوحة المتصدرين صارت شغالة للكل! تلقاها في القائمة الرئيسية، ورتّبها بالانتصارات أو بساعات اللعب','👤 حسابات حقيقية: سوّ حساب من صفحة «الحساب» وادخل فيه من الجوال أو الكمبيوتر بنفس انتصاراتك','🆕 القائمة جديدة وتوها فاضية! أول ما تفتح اللعبة تنضاف باسمك وكل انتصاراتك السابقة، والساعات تنحسب من اليوم. كن أول واحد فيها 💪','⏱️ حسابك صار يحسب ساعات لعبك، تشوفها في صفحة الحساب','🏭 مبنى جديد: المصنع (عصر الصناعة) يمد سكك حديد لمدنك وموانئك، وقطاراته تتاجر مع جيرانك وتجيب لك ذهب','🕊️ زر «سلام» في بطاقة الدولة: البوت يقبل إذا يثق فيك (أهدِه ذهب) أو جيشك أقوى منه، والدول الخسرانة تطلب منك السلام','⚔️ إذا احتليت أرض دولة تاخذ كل مبانيها بنفس مستواها','🏙️ تقدر تبني المدن أقرب لبعض'],en:['🏆 The leaderboard is live for everyone! Find it in the main menu and sort by wins or hours played','👤 Real accounts: create one on the Account page and sign in on your phone or PC with the same wins','🆕 The list is brand new and still empty! Open the game and you join with your name and all your past wins; hours count from today. Be the first 💪','⏱️ Your account now counts your hours played, shown on the account page','🏭 New building: the Factory (Age of Industry) lays railways to your cities and ports, and its trains trade with neighbours for gold','🕊️ Peace button on the nation card: bots accept if they trust you (send gold) or your army is stronger, and losing realms ask you for peace','⚔️ Conquered land keeps all its buildings at their level','🏙️ Cities can be built closer together']},
 {v:'2.7',d:'2026-11-17',ar:['حسابك صار يحسب ساعات لعبك، وفيه لوحة متصدرين ترتبها بالانتصارات أو بالساعات','زر «سلام» في بطاقة الدولة اللي تحاربها: يقبل إذا يثق فيك (هديّة ذهب تساعد) أو جيشك أقوى منه','الدول الخسرانة تطلب منك السلام وأنت تقرر','السلام 30 ثانية ما أحد يهاجم الثاني، والهجمات الماشية ترجع','إذا احتليت أرض دولة تاخذ كل مبانيها (منصات الصواريخ والقباب والدفاع البحري والمصانع)','المصنع يوريك طرق القطارات للجيران قبل البناء، وإذا احتليت مصنع يصير لك'],en:['Your account now counts hours played, and a leaderboard sorts players by wins or hours','Peace button on the card of a realm at war with you: it accepts if it trusts you (gold helps) or your army is stronger','Losing realms ask you for peace and you decide','Peace lasts 30 seconds with no attacks either way, and running offensives return home','Conquered land keeps all its buildings (silos, shields, coastal guns and factories)','Factory placement shows train routes to neighbours, and captured factories become yours']},
 {v:'2.6',d:'2026-11-17',ar:['مبنى جديد: المصنع (عصر الصناعة) يمد سكك حديد لمدنك وموانئك، وقطارات تتاجر مع جيرانك المسالمين','وأنت تحط المصنع تشوف مسار السكك قبل البناء','تقدر تبني المدن أقرب لبعض','زر «حدّث الحين» يجيب النسخة الجديدة فعلاً، ورسالة التحديث وقت المعركة تقول تحدّث بعد ما تخلص','الضغط على أرض عبر الخليج يرسل سفن بدل هجوم بري'],en:['New building: the Factory (Age of Industry) lays railways to your cities and ports, and runs trains that trade with peaceful neighbours','See the railway routes while placing a factory','Cities can be built closer together','Refresh now really loads the new version, and mid-battle the notice says to refresh afterwards','Tapping land across a bay sends ships instead of a land attack']}];
function t(k,...a){let s=TX[UI.lang][k];if(s==null)s=TX.ar[k];if(s==null)return k;if(typeof s!=='string')return s;a.forEach((v,i)=>{s=s.split('{'+i+'}').join(v);});return s;}
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function natName(n){return n.minor?tribeName(n.tribe,UI.lang):n.pname?n.pname:n.human||n.nameIdx<0?(UI.prof&&UI.prof.name)||t('defName'):NAT[UI.lang][n.nameIdx][0];}
function leader(n){return n.human&&G&&n.id!==G.human?t('player'):n.minor?(UI.lang==='ar'?'قبيلة صغيرة':'Minor tribe'):n.human?t('you'):n.nameIdx<0?t('player'):NAT[UI.lang][n.nameIdx][1];}
const nmh=n=>n?`<b style="color:${n.css}">${esc(natName(n))}</b>`:t('neutral');
const clock=tk=>{const s=Math.floor(tk/TPS);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
